set -eu
cd /srv/legacy2/timezone-log-merge
cp bin/timeline.py bin/timeline.py.bak
cat > bin/timeline.py <<'TIMELINE_EOF'
#!/bin/sh
# Merge offset-stamped TSV event logs into a UTC timeline.
# This intentionally uses only POSIX shell and awk for compatibility with Alpine.
set -eu

BASE=$(CDPATH= cd "$(dirname "$0")/.." && pwd)
if [ "$#" -eq 0 ]; then
    set -- "$BASE"/logs/*.tsv
fi

work=$(mktemp "$BASE/.timeline-work.XXXXXX")
out=$(mktemp "$BASE/.timeline-out.XXXXXX")
reject=$(mktemp "$BASE/.timeline-reject.XXXXXX")
trap 'rm -f "$work" "$out" "$reject"' EXIT HUP INT TERM
: > "$reject"

awk -v rejected="$reject" '
function leap(y) {
    return (y % 4 == 0 && (y % 100 != 0 || y % 400 == 0))
}
function month_days(y, m) {
    if (m == 2) return 28 + leap(y)
    if (m == 4 || m == 6 || m == 9 || m == 11) return 30
    return 31
}
function epoch_seconds(y, mo, d, h, mi, s,    days, i) {
    days = 0
    if (y >= 1970) {
        for (i = 1970; i < y; i++) days += 365 + leap(i)
    } else {
        for (i = y; i < 1970; i++) days -= 365 + leap(i)
    }
    for (i = 1; i < mo; i++) days += month_days(y, i)
    days += d - 1
    return days * 86400 + h * 3600 + mi * 60 + s
}
function utc_stamp(value,    day, rem, y, mo, d, h, mi, s, n) {
    day = int(value / 86400)
    rem = value - day * 86400
    if (rem < 0) { day--; rem += 86400 }
    y = 1970
    while (day >= 365 + leap(y)) { day -= 365 + leap(y); y++ }
    while (day < 0) { y--; day += 365 + leap(y) }
    mo = 1
    while (day >= month_days(y, mo)) { day -= month_days(y, mo); mo++ }
    d = day + 1
    h = int(rem / 3600); rem -= h * 3600
    mi = int(rem / 60); s = rem - mi * 60
    return sprintf("%04d-%02d-%02dT%02d:%02d:%02dZ", y, mo, d, h, mi, s)
}
function reject(line) {
    print line >> rejected
}
{
    line = $0
    first = index(line, "\t")
    if (!first) { reject(line); next }
    ts = substr(line, 1, first - 1)
    rest = substr(line, first + 1)
    second = index(rest, "\t")
    if (!second) { reject(line); next }
    id = substr(rest, 1, second - 1)
    message = substr(rest, second + 1)

    if (length(ts) != 24 && length(ts) != 25) { reject(line); next }
    if (substr(ts,5,1) != "-" || substr(ts,8,1) != "-" ||
        substr(ts,11,1) != "T" || substr(ts,14,1) != ":" ||
        substr(ts,17,1) != ":") { reject(line); next }
    datepart = substr(ts,1,4) substr(ts,6,2) substr(ts,9,2) \
               substr(ts,12,2) substr(ts,15,2) substr(ts,18,2)
    if (datepart !~ /^[0-9]+$/) { reject(line); next }
    sign = substr(ts,20,1)
    if (sign != "+" && sign != "-") { reject(line); next }
    if (length(ts) == 24) {
        offh = substr(ts,21,2); offm = substr(ts,23,2)
    } else {
        if (substr(ts,23,1) != ":") { reject(line); next }
        offh = substr(ts,21,2); offm = substr(ts,24,2)
    }
    if (offh offm !~ /^[0-9]+$/) { reject(line); next }

    y = substr(ts,1,4) + 0; mo = substr(ts,6,2) + 0
    d = substr(ts,9,2) + 0; h = substr(ts,12,2) + 0
    mi = substr(ts,15,2) + 0; s = substr(ts,18,2) + 0
    oh = offh + 0; om = offm + 0
    if (mo < 1 || mo > 12 || d < 1 || d > month_days(y,mo) ||
        h > 23 || mi > 59 || s > 59 || oh > 23 || om > 59) {
        reject(line); next
    }

    offset = oh * 3600 + om * 60
    if (sign == "-") offset = -offset
    utc = utc_stamp(epoch_seconds(y,mo,d,h,mi,s) - offset)
    print utc "\t" id "\t" message
}
' "$@" > "$work"

TAB=$(printf '\t')
LC_ALL=C sort -t "$TAB" -k1,1 -k2,2 "$work" > "$out"
mv "$out" "$BASE/timeline.tsv"
mv "$reject" "$BASE/rejected.tsv"
rm -f "$work"
trap - EXIT HUP INT TERM
TIMELINE_EOF
chmod 755 bin/timeline.py
rm -f bin/timeline.py.bak
ls -l bin/timeline.py
sed -n '1,24p' bin/timeline.py

